//! Reimplementation of the C++ `url_parser::URL` class (black-box compatible).
//!
//! Parsing pipeline (inferred from the reference binary's observable behavior):
//!   1. fragment: split at the first `#`
//!   2. query:    split the remainder at the first `?`
//!   3. scheme:   split the remainder at the first literal `://`
//!      (scheme text is unvalidated and ASCII-lowercased)
//!   4. authority: everything after `://` up to the first `/`; the rest is the path
//!   5. authority is re-serialized from userinfo / host / port parts
//!
//! All components are opaque byte strings: no percent-decoding, no case
//! folding (except the scheme), no trimming, no character validation.

/// A parsed URL. Construct with [`URL::new`], then inspect the components.
pub struct URL {
    scheme: Vec<u8>,
    authority: Vec<u8>,
    host: Vec<u8>,
    port: i32,
    path: Vec<u8>,
    query: Vec<u8>,
    fragment: Vec<u8>,
}

impl URL {
    /// Parse `url`, mirroring the reference C++ implementation.
    pub fn new(url: &[u8]) -> URL {
        // 1. Fragment: everything after the first '#'.
        let (mut rest, fragment) = match url.iter().position(|&c| c == b'#') {
            Some(i) => (&url[..i], url[i + 1..].to_vec()),
            None => (url, Vec::new()),
        };

        // 2. Query: everything after the first '?' in the remainder.
        let query = match rest.iter().position(|&c| c == b'?') {
            Some(i) => {
                let q = rest[i + 1..].to_vec();
                rest = &rest[..i];
                q
            }
            None => Vec::new(),
        };

        // 3. Scheme: everything before the first literal "://", lowercased.
        let (scheme, after_scheme) = match find_subslice(rest, b"://") {
            Some(i) => (to_lower_ascii(&rest[..i]), Some(&rest[i + 3..])),
            None => (Vec::new(), None),
        };

        // 4. Authority (up to the first '/') and path, only when a scheme
        //    delimiter was present; otherwise the whole remainder is the path.
        let (authority_raw, path) = match after_scheme {
            Some(s) => match s.iter().position(|&c| c == b'/') {
                Some(i) => (&s[..i], s[i..].to_vec()),
                None => (s, Vec::new()),
            },
            None => (&rest[..0], rest.to_vec()),
        };

        // 5. Split authority into userinfo / host / port and re-serialize it.
        let (authority, host, port) = parse_authority(authority_raw);

        URL {
            scheme,
            authority,
            host,
            port,
            path,
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &[u8] {
        &self.scheme
    }

    pub fn authority(&self) -> &[u8] {
        &self.authority
    }

    /// The port number, or -1 when absent or invalid.
    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &[u8] {
        &self.path
    }

    pub fn query(&self) -> &[u8] {
        &self.query
    }

    pub fn fragment(&self) -> &[u8] {
        &self.fragment
    }

    /// Valid iff the host part of the authority or the path is non-empty.
    pub fn is_valid(&self) -> bool {
        !self.host.is_empty() || !self.path.is_empty()
    }
}

/// Split `authority` at the first '@' into userinfo and hostport, then split
/// hostport at the first ':' into host and port text. Returns the
/// re-serialized authority, the host, and the port (-1 when invalid/absent).
fn parse_authority(authority: &[u8]) -> (Vec<u8>, Vec<u8>, i32) {
    let (userinfo, hostport) = match authority.iter().position(|&c| c == b'@') {
        Some(i) => (&authority[..i], &authority[i + 1..]),
        None => (&authority[..0], authority),
    };

    let (host, port_text) = match hostport.iter().position(|&c| c == b':') {
        Some(i) => (&hostport[..i], Some(&hostport[i + 1..])),
        None => (hostport, None),
    };

    let port = port_text.and_then(parse_port);

    let mut out = Vec::with_capacity(authority.len());
    if !userinfo.is_empty() {
        out.extend_from_slice(userinfo);
        out.push(b'@');
    }
    out.extend_from_slice(host);
    let port_num = match port {
        Some(p) => {
            out.push(b':');
            out.extend_from_slice(p.to_string().as_bytes());
            p as i32
        }
        None => -1,
    };

    (out, host.to_vec(), port_num)
}

/// strtol-style base-10 prefix parse: skip leading C-locale whitespace,
/// accept one optional sign, then consume digits up to the first non-digit.
/// Valid only when at least one digit was consumed and the value is in
/// [0, 65535] (`-0`/`+0` count as 0); negatives and overflow are rejected.
fn parse_port(text: &[u8]) -> Option<u16> {
    let mut i = 0;
    while i < text.len() && matches!(text[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    let mut negative = false;
    if i < text.len() && (text[i] == b'+' || text[i] == b'-') {
        negative = text[i] == b'-';
        i += 1;
    }

    let digits_start = i;
    let mut magnitude: u64 = 0;
    while i < text.len() && text[i].is_ascii_digit() {
        magnitude = magnitude
            .saturating_mul(10)
            .saturating_add((text[i] - b'0') as u64);
        i += 1;
    }

    if i == digits_start {
        return None; // no digits consumed
    }
    if negative && magnitude > 0 {
        return None; // negative ports rejected ('-0' is allowed)
    }
    if magnitude > 65535 {
        return None; // out of range / overflow
    }
    Some(magnitude as u16)
}

fn find_subslice(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    if needle.is_empty() || haystack.len() < needle.len() {
        return None;
    }
    haystack
        .windows(needle.len())
        .position(|window| window == needle)
}

fn to_lower_ascii(bytes: &[u8]) -> Vec<u8> {
    bytes.iter().map(|b| b.to_ascii_lowercase()).collect()
}

#[cfg(test)]
mod tests {
    use super::URL;

    fn fields(url: &str) -> (String, String, i32, String, String, String, bool) {
        let p = URL::new(url.as_bytes());
        (
            String::from_utf8_lossy(p.scheme()).into_owned(),
            String::from_utf8_lossy(p.authority()).into_owned(),
            p.port(),
            String::from_utf8_lossy(p.path()).into_owned(),
            String::from_utf8_lossy(p.query()).into_owned(),
            String::from_utf8_lossy(p.fragment()).into_owned(),
            p.is_valid(),
        )
    }

    #[test]
    fn basic() {
        assert_eq!(
            fields("http://example.com"),
            ("http".into(), "example.com".into(), -1, "".into(), "".into(), "".into(), true)
        );
        assert_eq!(
            fields("http://example.com:8080/path?query#frag"),
            ("http".into(), "example.com:8080".into(), 8080, "/path".into(), "query".into(), "frag".into(), true)
        );
        assert_eq!(
            fields("example.com"),
            ("".into(), "".into(), -1, "example.com".into(), "".into(), "".into(), true)
        );
        assert_eq!(
            fields(""),
            ("".into(), "".into(), -1, "".into(), "".into(), "".into(), false)
        );
    }

    #[test]
    fn scheme_rules() {
        assert_eq!(fields("HTTP://EXAMPLE.COM/PATH").0, "http");
        assert_eq!(fields("HTTP://EXAMPLE.COM/PATH").1, "EXAMPLE.COM");
        assert_eq!(fields("http:example.com").3, "http:example.com");
        assert_eq!(fields("://host").1, "host");
        assert_eq!(fields("a?b://c").4, "b://c"); // '?' hides the scheme
        assert_eq!(fields("a#b://c").5, "b://c");
        assert_eq!(fields("foo/bar://x.com").0, "foo/bar");
    }

    #[test]
    fn port_rules() {
        assert_eq!(fields("http://host:080").1, "host:80");
        assert_eq!(fields("http://host:65535").2, 65535);
        assert_eq!(fields("http://host:65536").1, "host");
        assert_eq!(fields("http://host:65536").2, -1);
        assert_eq!(fields("http://host:12ab").1, "host:12");
        assert_eq!(fields("http://host:abc").1, "host");
        assert_eq!(fields("http://host:").1, "host");
        assert_eq!(fields("http://host:+80").2, 80);
        assert_eq!(fields("http://host:-0").2, 0);
        assert_eq!(fields("http://host:-5").2, -1);
        assert_eq!(fields("http://host: 80").2, 80);
        assert_eq!(fields("http://host:99999999999999999999").2, -1);
        assert_eq!(fields("http://host:80:90").1, "host:80");
    }

    #[test]
    fn authority_userinfo() {
        assert_eq!(fields("http://user:pass@host:8080/p").1, "user:pass@host:8080");
        assert_eq!(fields("http://@x").1, "x");
        assert_eq!(fields("http://a@b@c/d").1, "a@b@c");
        assert_eq!(fields("http://user@").1, "user@");
        assert!(!fields("http://user@").6);
    }

    #[test]
    fn validity() {
        assert!(!fields("http://").6);
        assert!(!fields("http://?q").6);
        assert!(!fields("http://#f").6);
        assert!(!fields("?q").6);
        assert!(!fields("#f").6);
        assert!(!fields("http://:80").6);
        assert!(fields("http:///").6);
        assert!(fields(" ").6);
        assert!(fields("mailto:user@example.com").6);
        assert!(fields("http://:80/p").6);
    }

    #[test]
    fn query_fragment_precedence() {
        assert_eq!(fields("a?b#c?d#e").4, "b");
        assert_eq!(fields("a?b#c?d#e").5, "c?d#e");
        assert_eq!(fields("a#b?c").4, "");
        assert_eq!(fields("a#b?c").5, "b?c");
        assert_eq!(fields("http://h?a?b").4, "a?b");
        assert_eq!(fields("http://h##").5, "#");
    }
}

