    /// Parse `url`, mirroring the reference C++ implementation.
    pub fn new(url: &[u8]) -> URL {
        // 1. Fragment: everything after the first '#'.
        let (mut rest, fragment) = match url.iter().position(|&c| c == b'#') {
            Some(i) => (&url[..i], url[i + 1..].to_vec()),
            None => (url, Vec::new()),
        };

        // 2. Query: everything after the first '?' in the remainder.
        let query = match rest.iter().position(|&c| c == b'?') {
            Some(i) => {
                let q = rest[i + 1..].to_vec();
                rest = &rest[..i];
                q
            }
            None => Vec::new(),
        };

        // 3. Scheme: everything before the first literal "://", lowercased.
        let (scheme, after_scheme) = match find_subslice(rest, b"://") {
            Some(i) => (to_lower_ascii(&rest[..i]), Some(&rest[i + 3..])),
            None => (Vec::new(), None),
        };

