        //    delimiter was present; otherwise the whole remainder is the path.
        let (authority_raw, path) = match after_scheme {
            Some(s) => match s.iter().position(|&c| c == b'/') {
                Some(i) => (&s[..i], s[i..].to_vec()),
                None => (s, Vec::new()),
            },
            None => (&rest[..0], rest.to_vec()),
        };

        // 5. Split authority into userinfo / host / port and re-serialize it.
        let (authority, host, port) = parse_authority(authority_raw);

        URL {
            scheme,
            authority,
            host,
            port,
            path,
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &[u8] {
        &self.scheme
    }

    pub fn authority(&self) -> &[u8] {
        &self.authority
    }

    /// The port number, or -1 when absent or invalid.
    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &[u8] {
        &self.path
    }

    pub fn query(&self) -> &[u8] {
        &self.query
    }

    pub fn fragment(&self) -> &[u8] {
        &self.fragment
    }

    /// Valid iff the host part of the authority or the path is non-empty.
