/// hostport at the first ':' into host and port text. Returns the
/// re-serialized authority, the host, and the port (-1 when invalid/absent).
fn parse_authority(authority: &[u8]) -> (Vec<u8>, Vec<u8>, i32) {
    let (userinfo, hostport) = match authority.iter().position(|&c| c == b'@') {
        Some(i) => (&authority[..i], &authority[i + 1..]),
        None => (&authority[..0], authority),
    };

    let (host, port_text) = match hostport.iter().position(|&c| c == b':') {
        Some(i) => (&hostport[..i], Some(&hostport[i + 1..])),
        None => (hostport, None),
