        assert_eq!(fields("http://host:65535").2, 65535);
        assert_eq!(fields("http://host:65536").1, "host");
        assert_eq!(fields("http://host:65536").2, -1);
        assert_eq!(fields("http://host:12ab").1, "host:12");
        assert_eq!(fields("http://host:abc").1, "host");
        assert_eq!(fields("http://host:").1, "host");
        assert_eq!(fields("http://host:+80").2, 80);
        assert_eq!(fields("http://host:-0").2, 0);
        assert_eq!(fields("http://host:-5").2, -1);
        assert_eq!(fields("http://host: 80").2, 80);
        assert_eq!(fields("http://host:99999999999999999999").2, -1);
        assert_eq!(fields("http://host:80:90").1, "host:80");
    }

    #[test]
    fn authority_userinfo() {
        assert_eq!(fields("http://user:pass@host:8080/p").1, "user:pass@host:8080");
        assert_eq!(fields("http://@x").1, "x");
        assert_eq!(fields("http://a@b@c/d").1, "a@b@c");
        assert_eq!(fields("http://user@").1, "user@");
        assert!(!fields("http://user@").6);
    }

    #[test]
    fn validity() {
        assert!(!fields("http://").6);
        assert!(!fields("http://?q").6);
        assert!(!fields("http://#f").6);
        assert!(!fields("?q").6);
        assert!(!fields("#f").6);
        assert!(!fields("http://:80").6);
        assert!(fields("http:///").6);
        assert!(fields(" ").6);
        assert!(fields("mailto:user@example.com").6);
        assert!(fields("http://:80/p").6);
    }

    #[test]
    fn query_fragment_precedence() {
        assert_eq!(fields("a?b#c?d#e").4, "b");
        assert_eq!(fields("a?b#c?d#e").5, "c?d#e");
        assert_eq!(fields("a#b?c").4, "");
        assert_eq!(fields("a#b?c").5, "b?c");
        assert_eq!(fields("http://h?a?b").4, "a?b");
        assert_eq!(fields("http://h##").5, "#");
    }
}

