//! Entry point mirroring `test7.cpp`: parse argv[1] as a URL and print
//! scheme, authority, port, path, query, fragment, is_valid — one per line.
//! Exits with status 1 when no argument is given.

use std::io::Write;

use url_parser::URL;

fn main() {
    // args_os (not args) so non-UTF-8 arguments pass through unchanged,
    // exactly like C++ argv.
    let mut args = std::env::args_os();
    let _program = args.next();
    let url_arg = match args.next() {
        Some(arg) => arg,
        None => std::process::exit(1),
    };

    let url_bytes = os_bytes(&url_arg);
    let parser = URL::new(url_bytes);

    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    let mut line = |bytes: &[u8]| {
        let _ = out.write_all(bytes);
        let _ = out.write_all(b"\n");
    };

    line(parser.scheme());
    line(parser.authority());
    line(parser.port().to_string().as_bytes());
    line(parser.path());
    line(parser.query());
    line(parser.fragment());
    line(if parser.is_valid() { b"1" } else { b"0" });
}

#[cfg(unix)]
fn os_bytes(s: &std::ffi::OsString) -> &[u8] {
    use std::os::unix::ffi::OsStrExt;
    s.as_os_str().as_bytes()
}

#[cfg(not(unix))]
fn os_bytes(s: &std::ffi::OsString) -> &[u8] {
    s.to_str().unwrap_or("").as_bytes()
}

